#!/usr/bin/env bash
# fresh_build.sh — clean-room release build gate. Run from an EMPTY directory into which the
# release `lean/` tree (lakefile.lean = release lakefile with git-pinned mathlib, lean-toolchain,
# MPUP/, DiophCompression/, scripts/; lake-manifest.json is generated by `lake update` and is not part of the manifest) has been copied; optionally
# `../frozen_statements/` and `../certificates/definition_bodies.tsv` for the two fidelity gates.
# Any failure aborts with non-zero exit (set -euo pipefail). Writes every sub-log under logs/.
set -euo pipefail
cd "$(dirname "$0")"
export PATH="$HOME/.elan/bin:$PATH"; ulimit -n 8192
mkdir -p logs
sha256_file() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | awk '{print $1}'; else shasum -a 256 "$1" | awk '{print $1}'; fi; }
manifest() { # canonical source manifest: sorted (LC_ALL=C) list of "sha256  path" over all .lean/.py/.sh plus build metadata
  { find MPUP DiophCompression ResearchUpgrade scripts -type f \( -name '*.lean' -o -name '*.py' -o -name '*.sh' \) -print0; printf '%s\0' MPUP.lean DiophCompression.lean ResearchUpgrade.lean lakefile.lean lean-toolchain; } \
    | LC_ALL=C sort -z | while IFS= read -r -d '' f; do printf '%s  %s\n' "$(sha256_file "$f")" "$f"; done; }
echo "=== FRESH-CLONE RELEASE BUILD (release lakefile, empty dir, set -euo pipefail) ==="; date; hostname; pwd
echo "--- lean-toolchain ---"; cat lean-toolchain
echo "--- lakefile.lean ---"; cat lakefile.lean
manifest > logs/source_manifest_start.sha256
echo "SOURCE_MANIFEST_FILES=$(wc -l < logs/source_manifest_start.sha256 | tr -d ' ')"
echo "SRC_MANIFEST_SHA256=$(sha256_file logs/source_manifest_start.sha256)"
echo "=== lake update (fetch mathlib at pin) ==="; lake update > logs/lake_update.log 2>&1; echo "UPDATE_EXIT=0"; tail -3 logs/lake_update.log
echo "=== manifest mathlib rev ==="; python3 -c "import json;m=json.load(open('lake-manifest.json'));print('MATHLIB_REV=' + str([(p.get('rev'),p.get('inputRev')) for p in m['packages'] if p['name']=='mathlib']))"
echo "=== lake exe cache get ==="; lake exe cache get > logs/cache_get.log 2>&1; echo "CACHE_EXIT=0"; tail -3 logs/cache_get.log
echo "=== plain lake build (default target) ==="; lake build > logs/lake_build_plain.log 2>&1; echo "PLAIN_BUILD_EXIT=0"; tail -3 logs/lake_build_plain.log
echo "=== lake build DiophCompression ==="; lake build DiophCompression > logs/lake_build_dc.log 2>&1; echo "DC_BUILD_EXIT=0"; tail -3 logs/lake_build_dc.log
echo "=== lake build ResearchUpgrade (r40, third library) ==="; lake build ResearchUpgrade > logs/lake_build_ru.log 2>&1; echo "RU_BUILD_EXIT=0"; tail -3 logs/lake_build_ru.log
echo "=== lake build DiophCompression.QuadraticWitnessInertiaCore (all-r root) ==="; lake build DiophCompression.QuadraticWitnessInertiaCore > logs/minimal_all_r_build.log 2>&1; echo "CORE_BUILD_EXIT=0"; tail -3 logs/minimal_all_r_build.log
echo "=== rebuild.sh ==="; ./scripts/rebuild.sh > logs/rebuild.log 2>&1; echo "REBUILD_SH_EXIT=0"; grep -E "REBUILD_EXIT" logs/rebuild.log
echo "=== audit_ru.sh (r40: per-file kernel audit of ResearchUpgrade) ==="; ./scripts/audit_ru.sh > logs/audit_ru.log 2>&1; echo "AUDIT_RU_SH_EXIT=$?"; grep -E "AUDIT_RU_EXIT" logs/audit_ru.log
echo "=== audit_dc.sh (per-file kernel audit + forbidden-token gate) ==="; ./scripts/audit_dc.sh > logs/audit_dc.log 2>&1; echo "AUDIT_SH_EXIT=0"; grep -E "AUDIT_EXIT" logs/audit_dc.log
echo "=== axiom multiset (env phase, rebuild + audit) ==="
grep 'depends on axioms' logs/rebuild.log logs/audit_dc.log | sed -E 's/.*depends on axioms: //' | sort | uniq -c
echo "forbidden tokens in axiom lines: $( (grep 'depends on axioms' logs/rebuild.log logs/audit_dc.log | grep -cE 'sorryAx|native_decide|ofReduceBool|trustCompiler') || true)"
if [ -d ../frozen_statements ]; then
  echo "=== statement fidelity (theorems + definition signatures) ==="; STMT_BASE=../frozen_statements LEAN_BASE=. python3 scripts/statement_diff.py > logs/statement_diff.log 2>&1 || { echo "STATEMENT_DIFF_EXIT=1"; exit 1; }; grep -E '^(FROZEN_FILES|THEOREMS|DEFINITIONS|OPEN_REGISTRY|DUPLICATE_NAMES|FAIL)=' logs/statement_diff.log; echo "STATEMENT_DIFF_EXIT=0"
  echo "=== statement_diff controls (planted faults + Unicode-subscript identifiers, s25 / GPT Gate-1 必須A-6) ==="; STMT_BASE=../frozen_statements LEAN_BASE=. python3 scripts/statement_diff.py --negative-control > logs/statement_diff_negctrl.log 2>&1 || { echo "STATEMENT_DIFF_NEGCTRL_EXIT=1"; exit 1; }; grep -E '^NEG_CONTROL' logs/statement_diff_negctrl.log; STMT_BASE=../frozen_statements LEAN_BASE=. python3 scripts/statement_diff.py --unicode-control > logs/statement_diff_unicode.log 2>&1 || { echo "STATEMENT_DIFF_UNICODE_EXIT=1"; exit 1; }; grep -E '^UNICODE_CONTROL' logs/statement_diff_unicode.log; echo "STATEMENT_DIFF_CONTROLS_EXIT=0"
else echo "STATEMENT_DIFF_SKIPPED=no ../frozen_statements"; fi
if [ -f ../certificates/definition_bodies.tsv ]; then
  echo "=== definition body fidelity (elaborated TYPE/VALUE hashes vs frozen certificate) ==="; python3 scripts/definition_fidelity.py --check ../certificates/definition_bodies.tsv > logs/definition_fidelity.log 2>&1 || { grep -E '^(DEFFID|MISMATCH|MISSING|EXTRA)' logs/definition_fidelity.log; echo "DEFFID_CHECK_EXIT=1"; exit 1; }; grep -E '^DEFFID' logs/definition_fidelity.log; echo "DEFFID_CHECK_EXIT=0"
else echo "DEFFID_SKIPPED=no ../certificates/definition_bodies.tsv"; fi
echo "=== closures (static import / kernel constant dependency) ==="
lake env lean scripts/kernel_closure.lean > logs/kernel_closure.log 2>&1; echo "KERNEL_CLOSURE_LEAN_EXIT=0"; grep -oE 'KERNEL_CLOSURE_MODULES=[0-9]+ DC=[0-9]+ MPUP=[0-9]+|KERNEL_ABSENT [^ ]+=(YES|NO)' logs/kernel_closure.log
python3 scripts/static_closure.py --kernel-list logs/kernel_closure.log > logs/static_closure.log 2>&1; echo "STATIC_CLOSURE_PY_EXIT=0"; grep -E '^(STATIC_CLOSURE_MODULES|STATIC_CLOSURE_LOC|STATIC_ABSENT|KERNEL_SUBSET_STATIC|STATIC_ONLY_MODULES|STATIC_CLOSURE_EXIT)' logs/static_closure.log
python3 scripts/static_closure.py --negative-control | grep -E 'NEGATIVE_CONTROL'
echo "=== FINAL THEOREM AXIOM REPORT (sixteen exported theorems) ==="
lake env lean scripts/FinalAxiomReport.lean 2>&1 | tee logs/final_axioms.log; echo "FINAL_AXIOMS_EXIT=0"
# s28 gate fix: a root proved without any axiom prints "does not depend on any axioms" — stronger than
# std-3, but invisible to a plain 'depends on axioms' count. Count BOTH shapes, and report them apart.
python3 - logs/final_axioms.log <<'PYGATE'
import re, sys
t = open(sys.argv[1]).read()
std = {"propext", "Classical.choice", "Quot.sound"}
# One record per root. The axiom list may WRAP over several lines when the name is long, so parse the
# text, never line-by-line (s28: a line-based grep both miscounts and misjudges wrapped records).
withax = re.findall(r"' depends on axioms: \[(.*?)\]", t, re.S)
free   = len(re.findall(r"' does not depend on any axioms", t))
nonstd = 0
for ax in withax:
    names = {x.strip() for x in ax.replace("\n", " ").split(",") if x.strip()}
    if not names <= std:
        nonstd += 1
print("FINAL_AXIOM_LINES=%d" % (len(withax) + free))
print("FINAL_AXIOM_FREE_LINES=%d" % free)
print("FINAL_NONSTD3_LINES=%d" % nonstd)
PYGATE
echo "FINAL_STD3_ONLY=$( (grep -cE 'sorryAx|native_decide|ofReduceBool|trustCompiler' logs/final_axioms.log) || true)"
echo "=== RESEARCHUPGRADE AXIOM REPORT (r40: every declaration of the third library) ==="
lake env lean scripts/ResearchUpgradeAxiomReport.lean > logs/ru_axioms.log 2>&1; echo "RU_AXIOMS_EXIT=$?"
python3 - logs/ru_axioms.log <<'PYRU'
import re, sys
t = open(sys.argv[1]).read()
std = {"propext", "Classical.choice", "Quot.sound"}
withax = re.findall(r"' depends on axioms: \[(.*?)\]", t, re.S)
free   = len(re.findall(r"' does not depend on any axioms", t))
nonstd = sum(1 for ax in withax
             if not {x.strip() for x in ax.replace("\n", " ").split(",") if x.strip()} <= std)
print("RU_AXIOM_LINES=%d" % (len(withax) + free))
print("RU_AXIOM_FREE_LINES=%d" % free)
print("RU_NONSTD3_LINES=%d" % nonstd)
PYRU
echo "RU_FORBIDDEN=$( (grep -cE 'sorryAx|native_decide|ofReduceBool|trustCompiler' logs/ru_axioms.log) || true)"
RU_RECORDS=$( (grep -c "depends on axioms" logs/ru_axioms.log) || true)
echo "RU_RECORDS=$RU_RECORDS"
[ "$RU_RECORDS" -ge 700 ] || { echo "RU_RECORDS_GATE=FAIL (a gate that inspects nothing is not a gate)"; exit 1; }
# presence gate: the report must contain the theorems this round CLAIMS, by name.
RU_CAPS_MISSING=0
for c in QuadraticGraphData.summit_of_defines singleQuadratic_sharp_iff dim_le_of_summit \
         atomGraphZZ_capacity_eq_one exists_graph_injective_pad parity_not_quadratic \
         natInput_intInput_separation_at_two singleQuadratic_injective_dimension_sharp \
         not_atomGraphZZ_two \
         QuadraticGraphData.affine_of_offCentre_radical \
         generalWeakNF_iff_semidefiniteWeakNF \
         QuadraticGraphData.m_le_one_of_polarRankOne \
         QuadraticGraphData.witnessDir_inRadicalQ \
         FourSquareSlack.Family.residual_bounded \
         FourSquareSlack.Family.fullVectorCosetNF_of_intQuad_residual \
         Controls.sqrt2Floor_not_weakScalarCosetNF \
         intQuad_iff_totalDegree_le_two \
         QuadraticGraphData.eval_witness_invariant \
         QuadraticGraphData.noWitnessData_graph_iff \
         QuadraticGraphData.fullVectorCosetNF_of_polarRankOne \
         FourSquareSlack.Family.familyData_graph_iff \
         N4Control.D3_fullVectorCosetNF \
         FourSquareSlack.Family.total_and_outputUnique_iff \
         SaturatedLattice.smith_isUnit_of_saturated \
         QuadraticGraphData.rankExcess_compiler \
         RankExcessControl.sameGraph_three_witnessCounts \
         generalWeakNF_iff_definiteWeakNF \
         QuadraticGraphData.compiledData_posDef \
         RankExcessControl.exD_definite_reduction \
         SaturatedLattice.exists_unimodular_extension \
         FourSquareSlack.Family.singleQuadraticDefinable_of_family \
         NormLift.norm_section \
         NormLift.square_values_rigidity \
         definiteWeakNF_oneOut_oneWit_holds \
         lowRankSemidefiniteWeakNF_holds \
         QuadraticGraphData.definite_binary_compiler \
         FourSquareFinite.existsUnique_iff_gap \
         FourSquareFinite.full_residue_iff \
         FourSquareSlack.Family.total_and_outputUnique_iff_finite \
         FourSquareSlack.Family.graph_iff_table \
         QuadraticGraphData.fullVectorCosetNF_of_polarRank_eq_one \
         QuadraticGraphData.definite_binary_compiler_solutions \
         lowRankSemidefiniteWeakNF_allM_holds \
         QuadraticGraphData.constResidual_commonSlopeIntNF \
         QuadraticGraphData.constResidual_fullVectorCosetNF \
         affineSlope_unique \
         FourSquareSlack.Family.familyData_constResidualCentre \
         QuadraticGraphData.centreReflect_finite_iff \
         QuadraticGraphData.centreReflect_weakIntAffineCosetNF \
         QuadraticGraphData.centreReflect_coset_mod \
         QuadraticGraphData.shellEquiv \
         QuadraticGraphData.total_outputUnique_iff_shellImage \
         DefiniteShellControl.ctlC4_residueShell_zero_card \
         QuadraticGraphData.binary_baseSection \
         QuadraticGraphData.weakIntAffineCosetNF_of_binary \
         lowRankSemidefiniteIntAffineNF_holds \
         ShellControl.ctlN0_shellImage \
         ShellControl.ctlNeg_not_total \
         RankControl.d1_no_affine_section \
         RankControl.d1r4_no_affine_section \
         RankControl.ctlD1r4_total \
         QuadraticGraphData.symmetry_certificate_NF \
         isometry_integral_iff \
         IsometryControl.ctlD4_certificate_NF \
         generalWeakNF_iff_residualReflectionObstructionNF \
         lowRankSemidefiniteIntAffineNF_holds_viaBinary \
         RankControl.d1_no_quadratic_section \
         norm_totality_iff \
         QuadraticGraphData.lineSection_centredSlope_zero \
         QuadraticGraphData.rankTwo_CCR \
         rankTwoSemidefiniteFullNF_holds \
         CCRControls.threeSquares24_no_rational_affine_section \
         TCERBridge.localProgression \
         TCERBridge.ternaryCosetCollision_of_TCER \
         QuadraticGraphData.fixedCoset_slice \
         generalWeakNF_of_TCER \
         sealedWeakNF_of_TCER \
         ccr_of_TCER \
         semidefiniteFullNF_allRanks_of_TCER \
         generalFullNF_iff_branches \
         generalFullNF_iff_of_TCER \
         ccr_iff_oneInputOneOutput \
         linearBranchFullNF_holds \
         anisotropicIndefiniteFullNF_holds \
         generalFullNF_iff_isotropic_and_semidefinite \
         generalFullNF_iff_isotropic_of_TCER \
         QuadraticGraphData.false_of_offRadical_of_three_le_polarRank \
         isotropicBranchFullNF_of_three_le_polarRank \
         exists_scaling_divisor \
         QuadraticGraphData.constResidual_of_isotropic_polarRank_le_two \
         isotropicBranchFullNF_of_polarRank_le_two \
         isotropicBranchFullNF_holds \
         generalFullNF_iff_semidefiniteFullNF \
         generalFullNF_of_TCER \
         sealedFullNF_of_TCER \
         rank_hypothesis_needed \
         residual_zero_not_forced \
         sealedCommonSlopeNF_of_TCER \
         isotropic_three_le_polarRank_not_defines \
         singleQuadratic_of_commonSlope \
         singleQuadratic_iff_commonSlope_of_TCER \
         not_commonSlope_of_fullVectorCosetNF \
         rn_classify \
         scalar_singleQuadratic_iff_of_TCER \
         singleQuadratic_of_scalarFamilies \
         singleQuadratic_iff_commonSlope_of_TCER_of_ne_one \
         singleQuadratic_padZero_iff_of_TCER \
         commonSlope_comp \
         commonSlope_posDef_presentation \
         zeroWitness_iff \
         singleQuadratic_iff_uniqueWitness_of_TCER \
         floorThird_min_witnesses; do
  grep -q "ResearchUpgrade\.$c' depends on axioms" logs/ru_axioms.log || { echo "RU_CAPSTONE_ABSENT=$c"; RU_CAPS_MISSING=1; }
done
echo "RU_CAPS_MISSING=$RU_CAPS_MISSING"
[ "$RU_CAPS_MISSING" -eq 0 ] || { echo "RU_CAPSTONE_GATE=FAIL"; exit 1; }
grep -q 'error' logs/ru_axioms.log && { echo "RU_AXIOMS_GATE=FAIL (report did not elaborate)"; exit 1; }
echo "=== PAPER-CLAIM TYPE FINGERPRINTS (s39, Gate-13 A04) ==="
lake env lean scripts/PaperClaimTypeReport.lean > logs/paper_claim_types.log 2>&1; echo "TYPE_REPORT_EXIT=0"
grep -E '^(TYPE_CONTROLS|TYPE_MUT_CONTROLS|TYPE_ROWS|TYPE_MISSING)=' logs/paper_claim_types.log
grep -q '^TYPE_CONTROLS=4/4$' logs/paper_claim_types.log || { echo "TYPE_CONTROLS_GATE=FAIL"; exit 1; }
grep -q '^TYPE_MUT_CONTROLS=4/4$' logs/paper_claim_types.log || { echo "TYPE_MUT_CONTROLS_GATE=FAIL"; exit 1; }
grep -q '^TYPE_MISSING=0' logs/paper_claim_types.log || { echo "TYPE_MISSING_GATE=FAIL"; exit 1; }
echo "TYPE_REPORT_SHA256=$(sha256_file logs/paper_claim_types.log)"
echo "=== post-build source freeze check (manifest at end == manifest at start) ==="
manifest > logs/source_manifest_end.sha256
if cmp -s logs/source_manifest_start.sha256 logs/source_manifest_end.sha256; then echo "SOURCE_FREEZE=OK"; else echo "SOURCE_FREEZE=DRIFT"; diff logs/source_manifest_start.sha256 logs/source_manifest_end.sha256 || true; exit 1; fi
cp logs/source_manifest_end.sha256 source_manifest.sha256
echo "SOURCE_MANIFEST_FILE=source_manifest.sha256 sha256=$(sha256_file source_manifest.sha256)"
date; echo "FRESH_RELEASE_DONE"
